 1	/**
 2	 * Safety rails evaluated in PreToolUse. Each rail is a regex against a
 3	 * flattened view of the tool call ("<tool> <json input>") plus optional path checks.
 4	 */
 5	export interface Rail {
 6	  id: string;
 7	  match: string; // regex source, case-insensitive
 8	  tools?: string[]; // limit to these tools (default: all)
 9	  action: "deny" | "warn";
10	  reason: string;
11	}
12	
13	export interface RailHit {
14	  rail: Rail;
15	  action: "deny" | "warn";
16	  reason: string;
17	}
18	
19	export const DEFAULT_RAILS: Rail[] = [
20	  { id: "no-git-stash", match: "\\bgit\\s+stash\\b", tools: ["Bash"], action: "deny", reason: "git stash is forbidden in this repo (shared object store; clobbers other sessions)" },
21	  { id: "no-checkout-main", match: "\\bgit\\s+(-C\\s+\\S*Desktop/OmniRoute(?!/\\.claude/worktrees)\\S*\\s+)?(checkout|switch)\\b(?![^\\n]*worktrees)", tools: ["Bash"], action: "deny", reason: "never git checkout/switch in the shared main checkout — use the worktree" },
22	  { id: "no-pkill-pattern", match: "\\b(pkill\\s+-f|killall)\\b", tools: ["Bash"], action: "deny", reason: "pattern kills have taken down unrelated services — kill by PID only" },
23	  { id: "no-agent-instruction-edits", match: "(CLAUDE|AGENTS|GEMINI)\\.md", tools: ["Write", "Edit", "MultiEdit"], action: "deny", reason: "agent-instruction files need explicit operator approval" },
24	  { id: "no-rm-rf-home", match: "\\brm\\s+-rf?\\s+(~|\\$HOME|/Users/\\w+)(/?\\s|$)", tools: ["Bash"], action: "deny", reason: "refusing to delete a home directory" },
25	  { id: "warn-real-omp-config", match: "\\.omp/agent/(models|config)\\.ya?ml", action: "warn", reason: "touches Nick's real omp config — expected only for read/sha checks" },
26	  { id: "warn-live-db", match: "\\.omniroute/storage\\.sqlite(?!.*\\.backup)", tools: ["Bash"], action: "warn", reason: "touches the live OmniRoute database" },
27	];
28	
29	export function flattenToolCall(tool: string, input: unknown): string {
30	  if (input && typeof input === "object") {
31	    const o = input as Record<string, unknown>;
32	    const primary = (o.command ?? o.file_path ?? o.path ?? o.pattern ?? "") as string;
33	    return `${tool} ${primary} ${JSON.stringify(o)}`;
34	  }
35	  return `${tool} ${String(input ?? "")}`;
36	}
37	
38	export function evaluateRails(rails: Rail[], tool: string, input: unknown): RailHit[] {
39	  const text = flattenToolCall(tool, input);
40	  const hits: RailHit[] = [];
41	  for (const rail of rails) {
42	    if (rail.tools && !rail.tools.includes(tool)) continue;
43	    let re: RegExp;
44	    try { re = new RegExp(rail.match, "i"); } catch { continue; }
45	    if (re.test(text)) hits.push({ rail, action: rail.action, reason: rail.reason });
46	  }
47	  // deny wins over warn
48	  return hits.sort((a, b) => (a.action === b.action ? 0 : a.action === "deny" ? -1 : 1));
49	}
