 7	const RailSchema = z.object({ id: z.string(), match: z.string(), tools: z.array(z.string()).optional(), action: z.enum(["deny", "warn"]), reason: z.string() });
 8	const ProbeSchema = z.object({ name: z.string(), url: z.string().optional(), command: z.string().optional(), intervalSec: z.number().default(20), expect: z.string().optional() });
 9	
10	export const ConfigSchema = z.object({
11	  model: z.string().default("cc/claude-fable-5-1"),
12	  baseUrl: z.string().optional(),
13	  authToken: z.string().optional(),
14	  authTokenEnv: z.string().default("VIGIL_AUTH_TOKEN"),
15	  cwd: z.string().optional(),
16	  approvals: z.enum(["auto", "gates", "all"]).default("auto"),
17	  maxTurns: z.number().default(400),
18	  maxBudgetUsd: z.number().optional(),
19	  unsetEnv: z.array(z.string()).default(["NODE_ENV"]),
20	  env: z.record(z.string(), z.string()).default({}),
21	  addDirs: z.array(z.string()).default([]),
22	  rails: z.array(RailSchema).default(DEFAULT_RAILS),
23	  probes: z.array(ProbeSchema).default([]),
24	  /** Claude Code settings the agent loads. Default [] = a clean agent: no user plugins/hooks/skills/env overrides leaking into the run. */
25	  settingSources: z.array(z.enum(["user", "project", "local"])).default([]),
26	  animations: z.boolean().default(true),
27	  logLevel: z.enum(["debug", "info", "warn"]).default("info"),
28	});
29	export type VigilConfig = z.infer<typeof ConfigSchema>;
30	
31	export function loadConfig(explicit?: string): { config: VigilConfig; source: string } {
32	  const candidates = [explicit, resolve("vigil.config.json"), resolve(homedir(), ".config/vigil/config.json")].filter(Boolean) as string[];
33	  for (const c of candidates) {
34	    if (existsSync(c)) {
35	      const raw = JSON.parse(readFileSync(c, "utf8"));
36	      return { config: ConfigSchema.parse(raw), source: c };
37	    }
38	  }
39	  return { config: ConfigSchema.parse({}), source: "(defaults)" };
40	}
