42	/** Env for the SDK child: inherit, unset the listed names, apply overrides, route to baseUrl/token. */
43	export function buildEnv(cfg: VigilConfig, overrides: Record<string, string> = {}): Record<string, string> {
44	  const env: Record<string, string> = {};
45	  for (const [k, v] of Object.entries(process.env)) if (v !== undefined && !cfg.unsetEnv.includes(k)) env[k] = v;
46	  Object.assign(env, cfg.env, overrides);
47	  if (cfg.baseUrl) env.ANTHROPIC_BASE_URL = cfg.baseUrl;
48	  const token = cfg.authToken ?? process.env[cfg.authTokenEnv];
49	  if (token) env.ANTHROPIC_AUTH_TOKEN = token;
50	  return env;
51	}
