/**
 * Safety rails evaluated in PreToolUse. Each rail is a regex against a
 * flattened view of the tool call ("<tool> <json input>") plus optional path checks.
 */
export interface Rail {
  id: string;
  match: string; // regex source, case-insensitive
  tools?: string[]; // limit to these tools (default: all)
  action: "deny" | "warn";
  reason: string;
}

export interface RailHit {
  rail: Rail;
  action: "deny" | "warn";
  reason: string;
}

export const DEFAULT_RAILS: Rail[] = [
  { id: "no-git-stash", match: "\\bgit\\s+stash\\b", tools: ["Bash"], action: "deny", reason: "git stash is forbidden in this repo (shared object store; clobbers other sessions)" },
  { id: "no-checkout-main", match: "\\bgit\\s+(-C\\s+\\S*Desktop/OmniRoute(?!/\\.claude/worktrees)\\S*\\s+)?(checkout|switch)\\b(?![^\\n]*worktrees)", tools: ["Bash"], action: "deny", reason: "never git checkout/switch in the shared main checkout — use the worktree" },
  { id: "no-pkill-pattern", match: "\\b(pkill\\s+-f|killall)\\b", tools: ["Bash"], action: "deny", reason: "pattern kills have taken down unrelated services — kill by PID only" },
