export function flattenToolCall(tool: string, input: unknown): string {
  if (input && typeof input === "object") {
    const o = input as Record<string, unknown>;
    const primary = (o.command ?? o.file_path ?? o.path ?? o.pattern ?? "") as string;
    return `${tool} ${primary} ${JSON.stringify(o)}`;
  }
  return `${tool} ${String(input ?? "")}`;
}

export function evaluateRails(rails: Rail[], tool: string, input: unknown): RailHit[] {
  const text = flattenToolCall(tool, input);
  const hits: RailHit[] = [];
  for (const rail of rails) {
    if (rail.tools && !rail.tools.includes(tool)) continue;
    let re: RegExp;
    try { re = new RegExp(rail.match, "i"); } catch { continue; }
    if (re.test(text)) hits.push({ rail, action: rail.action, reason: rail.reason });
  }
  // deny wins over warn
  return hits.sort((a, b) => (a.action === b.action ? 0 : a.action === "deny" ? -1 : 1));
}

