const RailSchema = z.object({ id: z.string(), match: z.string(), tools: z.array(z.string()).optional(), action: z.enum(["deny", "warn"]), reason: z.string() });
const ProbeSchema = z.object({ name: z.string(), url: z.string().optional(), command: z.string().optional(), intervalSec: z.number().default(20), expect: z.string().optional() });

export const ConfigSchema = z.object({
  model: z.string().default("cc/claude-fable-5-1"),
  baseUrl: z.string().optional(),
  authToken: z.string().optional(),
  authTokenEnv: z.string().default("VIGIL_AUTH_TOKEN"),
  cwd: z.string().optional(),
  approvals: z.enum(["auto", "gates", "all"]).default("auto"),
  maxTurns: z.number().default(400),
  maxBudgetUsd: z.number().optional(),
  unsetEnv: z.array(z.string()).default(["NODE_ENV"]),
  env: z.record(z.string(), z.string()).default({}),
  addDirs: z.array(z.string()).default([]),
  rails: z.array(RailSchema).default(DEFAULT_RAILS),
  probes: z.array(ProbeSchema).default([]),
  /** Claude Code settings the agent loads. Default [] = a clean agent: no user plugins/hooks/skills/env overrides leaking into the run. */
  settingSources: z.array(z.enum(["user", "project", "local"])).default([]),
  animations: z.boolean().default(true),
  logLevel: z.enum(["debug", "info", "warn"]).default("info"),
});
export type VigilConfig = z.infer<typeof ConfigSchema>;

export function loadConfig(explicit?: string): { config: VigilConfig; source: string } {
  const candidates = [explicit, resolve("vigil.config.json"), resolve(homedir(), ".config/vigil/config.json")].filter(Boolean) as string[];
  for (const c of candidates) {
    if (existsSync(c)) {
      const raw = JSON.parse(readFileSync(c, "utf8"));
      return { config: ConfigSchema.parse(raw), source: c };
    }
  }
  return { config: ConfigSchema.parse({}), source: "(defaults)" };
}

/** Env for the SDK child: inherit, unset the listed names, apply overrides, route to baseUrl/token. */
export function buildEnv(cfg: VigilConfig, overrides: Record<string, string> = {}): Record<string, string> {
  const env: Record<string, string> = {};
  for (const [k, v] of Object.entries(process.env)) if (v !== undefined && !cfg.unsetEnv.includes(k)) env[k] = v;
  Object.assign(env, cfg.env, overrides);
  if (cfg.baseUrl) env.ANTHROPIC_BASE_URL = cfg.baseUrl;
  const token = cfg.authToken ?? process.env[cfg.authTokenEnv];
  if (token) env.ANTHROPIC_AUTH_TOKEN = token;
  return env;
}
